/**
 * Fully Offline Inlined Segoe UI font suite for Vietnamese receipts
 * Embedded directly as Base64 Data URIs for 100% synchronous availability
 * across all platforms (iOS WKWebView, Android Capacitor, Sunmi POS, Windows, Mac).
 *
 * Includes:
 *  - Segoe UI Regular (400)
 *  - Segoe UI Semibold (600) — Calibrated to match Lao Saysettha Bold thermal stroke width (4.3px)
 *  - Segoe UI Bold (700)
 */

export const SEGOE_UI_REGULAR_B64 = "";
export const SEGOE_UI_SEMIBOLD_B64 = "";
export const SEGOE_UI_BOLD_B64 = "";

export const SEGOE_UI_CSS = `
@font-face {
  font-family: 'Segoe UI';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url(data:font/truetype;charset=utf-8;base64,${SEGOE_UI_REGULAR_B64}) format('truetype');
}
@font-face {
  font-family: 'Segoe UI';
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url(data:font/truetype;charset=utf-8;base64,${SEGOE_UI_SEMIBOLD_B64}) format('truetype');
}
@font-face {
  font-family: 'Segoe UI';
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url(data:font/truetype;charset=utf-8;base64,${SEGOE_UI_SEMIBOLD_B64}) format('truetype');
}
@font-face {
  font-family: 'Segoe UI';
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url(data:font/truetype;charset=utf-8;base64,${SEGOE_UI_BOLD_B64}) format('truetype');
}
@font-face {
  font-family: 'Segoe UI';
  font-style: normal;
  font-weight: bold;
  font-display: swap;
  src: url(data:font/truetype;charset=utf-8;base64,${SEGOE_UI_BOLD_B64}) format('truetype');
}
`;

let segoeUiLoadedPromise = null;

export async function ensureSegoeUiLoaded() {
  if (typeof document === 'undefined') return;
  if (segoeUiLoadedPromise) return segoeUiLoadedPromise;

  segoeUiLoadedPromise = (async () => {
    try {
      // 1. Inject @font-face style tag with embedded Base64 fonts
      if (!document.getElementById('segoeui-base64-style')) {
        const style = document.createElement('style');
        style.id = 'segoeui-base64-style';
        style.textContent = SEGOE_UI_CSS;
        document.head.appendChild(style);
      }

      // 2. Load via FontFace API for instant canvas availability
      if (document.fonts && typeof FontFace !== 'undefined') {
        const sReg = new FontFace(
          'Segoe UI',
          `url(data:font/truetype;charset=utf-8;base64,${SEGOE_UI_REGULAR_B64})`,
          { weight: '400', style: 'normal' }
        );
        const sMedium = new FontFace(
          'Segoe UI',
          `url(data:font/truetype;charset=utf-8;base64,${SEGOE_UI_SEMIBOLD_B64})`,
          { weight: '500', style: 'normal' }
        );
        const sSemiBold = new FontFace(
          'Segoe UI',
          `url(data:font/truetype;charset=utf-8;base64,${SEGOE_UI_SEMIBOLD_B64})`,
          { weight: '600', style: 'normal' }
        );
        const sBold = new FontFace(
          'Segoe UI',
          `url(data:font/truetype;charset=utf-8;base64,${SEGOE_UI_BOLD_B64})`,
          { weight: '700', style: 'normal' }
        );

        const faces = await Promise.all([
          sReg.load().catch((e) => { console.warn('Segoe UI Reg load notice:', e); return null; }),
          sMedium.load().catch((e) => { console.warn('Segoe UI Med load notice:', e); return null; }),
          sSemiBold.load().catch((e) => { console.warn('Segoe UI SemiBold load notice:', e); return null; }),
          sBold.load().catch((e) => { console.warn('Segoe UI Bold load notice:', e); return null; }),
        ]);

        faces.forEach((f) => {
          if (f) document.fonts.add(f);
        });

        await document.fonts.ready;
      }
    } catch (err) {
      console.warn('[segoeUiFont] Font loading notice:', err);
    }
  })();

  return segoeUiLoadedPromise;
}

export default ensureSegoeUiLoaded;
